"""Explain cache exceptions, device tracking and configuration-specific APIs."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1873': ('설명서의 짧은 요약 뒤에는 특별한 경우의 규칙이 있을 수 있어요. 모든 물건에 같은 표시를 붙인다고 생각하기 전에 실제 조건을 살펴봐요.', 'slab 예외 조건과 큰 할당의 요청 길이·해제 범위를 구별합니다.', '일반 cache·RCU cache·생성 함수가 있는 cache 세 줄을 적고 poison까지 가는지 표시하세요.', ['slab은 비슷한 크기의 커널 객체를 효율적으로 할당하는 방식이에요. cache는 여기서 그런 객체를 관리하는 묶음이에요. KMSAN 헤더는 해제된 객체를 미준비 상태로 표시한다고 요약해요. poison은 실제 내용을 망가뜨리는 것이 아니라 검사 정보에 표시하는 일이에요.', 'kmsan_slab_free의 실제 본문은 검사가 꺼져 있거나 검사 도구 내부 작업 중이면 돌아가요. 이어 특별한 cache 조건을 확인해요. 따라서 설명 한 줄만 보고 모든 호출이 poison까지 간다고 생각하면 안 돼요.', 'SLAB_TYPESAFE_BY_RCU 표시가 있는 cache면 돌아가요. RCU는 여러 작업이 동시에 자료를 읽고 바꿀 때 수명을 조절하는 방식이에요. 이 cache의 사용 규칙 때문에 일반 객체와 같은 순간에 poison하지 않는 예외예요. 해제 뒤 언제든 안전하게 써도 된다는 허락은 아니에요.', 'ctor, 즉 객체 준비를 담당하는 생성 함수가 있는 cache도 돌아가요. 원문은 다음 할당까지 상태를 유지해야 한다고 설명해요. 두 예외를 지나면 object_size 길이에 해제 표시를 포함한 poison을 요청해요.', '큰 할당의 kmsan_kmalloc_large는 받은 size 길이를 추적해요. 반면 kmsan_kfree_large는 블록의 선두 페이지를 찾아 page_size(page) 길이를 써요. 요청한 길이와 확보한 페이지 블록 크기는 다른 정보예요.', '예를 들어 요청 길이가 9000바이트여도 그것만으로 해제 블록 크기가 정확히 9000이라고 결론내릴 수 없어요. 실제 page_size는 페이지 구조에서 확인해야 해요. 요청 길이·확보 크기·검사 범위를 같은 숫자로 뭉뚱그리지 마세요.'], [('slab free의 짧은 설명만 보고 모든 cache를 poison한다고 판단해도 되나요?', ['네. 요약 한 줄이 모든 실행 조건을 담아요', '아니요. 실제 본문에는 특별한 cache의 조기 반환이 있어요'], '정답은 두 번째예요. RCU cache와 생성 함수가 있는 cache의 예외를 확인해야 해요. 일반 설명과 실제 조건을 함께 읽으세요.'), ('큰 할당의 size와 큰 해제의 page_size는 반드시 같은 값인가요?', ['아니요. 요청 길이와 페이지 블록 크기는 서로 다른 정보예요', '네. 모든 요청은 정확히 페이지 블록 전체 크기예요'], '정답은 첫 번째예요. 할당 추적에는 받은 size, 해제 추적에는 page_size(page)를 써요. 실제 값을 확인하지 않고 둘을 같다고 놓으면 범위를 잘못 이해해요.')]), 'os1874': ('짐을 보내기 전에 내용을 확인하는 일과 택배차를 운전하는 일은 달라요. 이 도우미는 전송 방향에 맞춰 검사 정보를 다뤄요.', 'DMA·여러 조각 목록·USB 요청의 표현과 검사 역할을 이해합니다.', '컴퓨터→장치는 검사, 장치→컴퓨터는 준비됨 표시, 양방향은 검사→표시로 적으세요.', ['DMA는 장치와 메모리 사이의 데이터 이동을 지원하는 방식이에요. kmsan_handle_dma는 시작 페이지 page, 페이지 안 시작 위치 offset, 길이 size, 방향 dir를 받아요. 이 정보는 어느 범위를 어떤 방향으로 다루는지 알려 줘요.', '장치로 보내는 DMA_TO_DEVICE는 내용이 준비됐는지 검사해요. 장치에서 들어오는 DMA_FROM_DEVICE는 검사 정보를 준비됨으로 바꿔요. 양방향 DMA_BIDIRECTIONAL은 검사한 뒤 준비됨 표시를 해요. DMA_NONE은 이 방향 분기에서 아무 처리를 하지 않아요.', '문서의 initialize라는 표현은 이 구현에서 검사 정보의 unpoison을 가리켜요. 실제 데이터에 값을 써 넣거나 DMA 장치를 직접 작동시키는 것이 아니에요. 전송을 시작하고 완료하는 코드는 별도로 있어요.', 'SG는 scatter-gather의 줄임말로 흩어진 여러 메모리 조각을 목록으로 표현하는 방식이에요. 각 항목에는 페이지, 시작 위치 offset, 길이 length가 있어요. nents는 처리할 항목 수이고 반복 도우미가 항목을 따라 DMA 검사 함수에 넘겨요.', 'USB 쪽 URB는 전송 요청을 담는 구조예요. is_out이 참이면 장치로 보낼 버퍼를 검사하고, 거짓이면 준비됨 표시를 해요. 버퍼는 전송 데이터를 담는 메모리 공간이라는 뜻이에요.', '따라서 이 함수들을 불렀다는 사실만으로 실제 장치가 전송을 끝냈거나 모든 데이터가 올바르다고 증명되지는 않아요. 원문에는 highmem 페이지에서 돌아가는 등 별도 조건도 있어요. 공개 선언의 방향 규칙과 실제 구현의 조건을 함께 확인하세요.'], [('KMSAN DMA 도우미를 호출하면 이 함수가 실제 장치 전송까지 직접 수행하나요?', ['네. 모든 DMA 장치를 직접 작동시켜 전송을 끝내요', '아니요. 방향에 맞는 검사와 준비 상태 표시를 처리해요'], '정답은 두 번째예요. 전송에 쓰는 자료의 검사 정보를 다루는 역할이에요. 실제 전송 요청과 완료 처리는 별도 코드에서 확인해야 해요.'), ('SG 목록은 각 메모리 조각을 어떻게 나타내나요?', ['페이지·시작 위치·길이가 있는 항목으로 나타내요', '언제나 하나의 연속된 사용자 문자열로 나타내요'], '정답은 첫 번째예요. 여러 조각은 위치와 길이가 각각 다를 수 있어요. 목록 항목을 따라 범위를 전달하는 것이므로 단일 문자열이라고 볼 수 없어요.')]), 'os1875': ('두 안내문이 다르면 실제 입구에서 무엇을 확인하는지 살펴봐요. 문서의 비교 문장과 현재 코드의 조건이 다를 수 있어요.', 'entry_regs 설명과 일반 unpoison 구현의 차이를 확인합니다.', '일반 unpoison은 enabled 확인, entry_regs는 주소와 sizeof(*regs)를 전달한다고 나란히 적으세요.', ['unpoison은 검사 정보를 준비됨으로 바꾸는 일이에요. kmsan_unpoison_entry_regs는 인터럽트 진입 등의 낮은 수준 코드에서 저장한 레지스터 영역을 다루는 도우미예요. 레지스터는 CPU 안의 작은 저장 공간이에요.', '헤더 설명은 entry_regs가 일반 unpoison과 달리 검사 도구 내부에서도 불릴 수 있다고 비교해요. 하지만 이 고정 버전의 hooks.c에서 실제 일반 kmsan_unpoison_memory는 kmsan_enabled만 확인해요.', '일반 함수에는 kmsan_in_runtime이면 돌아가라는 조건이 없어요. 구현 주석도 추가 할당이나 검사 코드 호출을 일으키지 않아 내부에서 사용할 수 있다고 설명해요. 따라서 헤더의 대비 문장을 그대로 실행 조건으로 외우면 실제 코드와 어긋나요.', 'entry_regs 본문은 kmsan_unpoison_memory((void *)regs, sizeof(*regs))를 호출해요. 즉 일반 함수를 감싸서 레지스터 저장 영역의 주소와 구조체 크기를 알맞게 전달해 주는 역할이에요.', 'regs는 주소를 담는 포인터이고 *regs는 그 주소가 가리키는 구조체를 뜻해요. sizeof(*regs)는 구조체 크기이지 포인터 변수 크기가 아니에요. 실제 구조체 크기는 컴퓨터 구조의 정의에 따라 달라요.', '이 함수가 실제 CPU 레지스터를 저장하는 것은 아니에요. 저장해 둔 영역의 검사 정보를 갱신해요. 주석이 설명하는 의도, 일반 함수의 실제 입구 조건, 짧은 wrapper가 전달하는 인자를 각각 나눠 읽으세요.'], [('실제 일반 kmsan_unpoison_memory는 검사 도구 내부라는 이유만으로 언제나 돌아가나요?', ['네. 헤더의 비교 문장이 있으므로 반드시 그런 조건이 있어요', '아니요. 이 구현의 입구는 enabled만 확인해요'], '정답은 두 번째예요. 실제 본문에 runtime 조기 반환 조건이 없어요. 설명과 코드가 어긋나는 부분은 코드와 함께 확인해 기록해야 해요.'), ('entry_regs가 일반 unpoison에 넘기는 길이는 무엇인가요?', ['sizeof(*regs), 즉 가리키는 구조체 크기예요', '언제나 포인터 변수 하나의 크기예요'], '정답은 첫 번째예요. 주소 쪽지의 크기와 그 주소에 있는 자료의 크기는 달라요. 별표가 있는 식은 대상 구조체 형식의 크기를 구해요.')]), 'os1876': ('점검표를 찾는 창구가 없을 수도 있고, 창구가 있어도 찾는 표가 없을 수 있어요. 함수의 존재 여부와 반환 결과를 따로 확인해요.', '검사 정보 조회의 NULL 반환과 설정별 API 가용성을 이해합니다.', '설정에 선언이 있는지 확인→조회→결과가 NULL인지 확인이라는 순서를 적으세요.', ['kmsan_get_metadata는 지정한 커널 주소에 대응하는 검사 정보의 위치를 찾는 함수예요. is_origin이 거짓이면 준비 상태 shadow, 참이면 발생 원인 origin을 선택해요. 반환값은 실제 데이터 자체가 아니라 검사 정보를 가리키는 포인터예요.', '공개 계약은 검사 정보를 찾지 못하면 NULL을 반환한다고 설명해요. NULL은 여기서 사용할 검사 정보 포인터가 없다는 표시예요. 대신 원래 데이터 주소를 아무렇게나 돌려주는 것이 아니에요.', '구현은 주소 종류에 따라 가상 메모리 영역, 기종별 정보, 일반 페이지 정보를 찾아요. 일반 페이지를 얻지 못하거나 페이지에 검사 정보가 없으면 NULL을 반환해요. 호출자는 결과가 필요한 곳에서 없음 가능성을 처리해야 해요.', '검사 정보 포인터가 없다는 것이 데이터 값이 0이라는 뜻은 아니에요. 반대로 포인터가 있다는 사실만으로 실제 내용이 안전하다는 결론도 나오지 않아요. 조회는 정보의 위치를 얻는 단계예요.', '이 헤더는 CONFIG_KMSAN을 넣은 쪽에 getter를 선언하지만, 설정을 끈 #else 쪽에는 같은 getter의 빈 대체 함수가 없어요. 다른 hook에 대체 함수가 있다고 모든 함수가 자동으로 제공되는 것은 아니에요.', '따라서 코드에서 호출하려면 사용하는 빌드 설정과 실제 선언을 확인해야 해요. 전처리는 설정에 따라 코드 조각을 선택하는 과정이에요. 선택되지 않은 쪽에 이름이 보인다는 이유만으로 모든 설정에서 호출할 수 있다고 가정하지 마세요.'], [('검사 정보 getter가 해당 정보를 찾지 못하면 반환하는 값은 무엇인가요?', ['언제나 실제 데이터의 주소예요', 'NULL이에요'], '정답은 두 번째예요. 검사 정보를 가리킬 수 없다는 뜻이에요. NULL을 데이터 내용 0이나 안전성 검사 합격으로 해석하면 안 돼요.'), ('설정을 끈 헤더 분기에도 모든 활성 API의 대체 함수가 똑같이 있나요?', ['아니요. 이 getter처럼 대체 정의가 없는 함수도 확인해야 해요', '네. 어느 쪽에 이름만 보이면 모든 설정에서 쓸 수 있어요'], '정답은 첫 번째예요. CONFIG_KMSAN 분기에 있는 선언과 #else의 정의 목록을 각각 보세요. 기능 사용 조건에는 함수가 그 설정에서 제공되는지도 포함돼요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_464.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
